        PropertyMetadata(name='geo_equals', schema_name='geoEquals', schema_url='https://schema.org/geoEquals', ranges=('GeospatialGeometry', 'Place'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('GeospatialGeometry', 'Place'), external_domains=(), comment='Represents spatial relations in which two geometries (or the places they represent) are topologically equal, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM). "Two geometries are topologically equal if their interiors intersect and no part of the interior or boundary of one geometry intersects the exterior of the other" (a symmetric relationship).', label='geoEquals', contributors=(), sources=()),
        PropertyMetadata(name='geo_intersects', schema_name='geoIntersects', schema_url='https://schema.org/geoIntersects', ranges=('GeospatialGeometry', 'Place'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('GeospatialGeometry', 'Place'), external_domains=(), comment='Represents spatial relations in which two geometries (or the places they represent) have at least one point in common. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).', label='geoIntersects', contributors=(), sources=()),
        PropertyMetadata(name='geo_overlaps', schema_name='geoOverlaps', schema_url='https://schema.org/geoOverlaps', ranges=('GeospatialGeometry', 'Place'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('GeospatialGeometry', 'Place'), external_domains=(), comment='Represents a relationship between two geometries (or the places they represent), relating a geometry to another that geospatially overlaps it, i.e. they have some but not all points in common. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).', label='geoOverlaps', contributors=(), sources=()),
        PropertyMetadata(name='geo_touches', schema_name='geoTouches', schema_url='https://schema.org/geoTouches', ranges=('GeospatialGeometry', 'Place'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('GeospatialGeometry', 'Place'), external_domains=(), comment='Represents spatial relations in which two geometries (or the places they represent) touch: "they have at least one boundary point in common, but no interior points." (A symmetric relationship, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).)', label='geoTouches', contributors=(), sources=()),
        PropertyMetadata(name='geo_within', schema_name='geoWithin', schema_url='https://schema.org/geoWithin', ranges=('GeospatialGeometry', 'Place'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('GeospatialGeometry', 'Place'), external_domains=(), comment='Represents a relationship between two geometries (or the places they represent), relating a geometry to one that contains it, i.e. it is inside (i.e. within) its interior. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).', label='geoWithin', contributors=(), sources=()),
        PropertyMetadata(name='global_location_number', schema_name='globalLocationNumber', schema_url='https://schema.org/globalLocationNumber', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#gLNId', 'https://ref.gs1.org/voc/globalLocationNumber'), subproperty_of=('identifier',), domains=('Organization', 'Person', 'Place'), external_domains=(), comment='The [Global Location Number](http://www.gs1.org/gln) (GLN, sometimes also referred to as International Location Number or ILN) of the respective organization, person, or place. The GLN is a 13-digit number used to identify parties and physical locations.', label='globalLocationNumber', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
